alter table public.bella_app_config add column if not exists chat_ai_enabled boolean not null default true, add column if not exists voice_enabled boolean not null default true, add column if not exists ai_activities_enabled boolean not null default true, add column if not exists moments_enabled boolean not null default true;
alter table public.bella_account_admin add column if not exists leaderboard_blocked boolean not null default false;

create or replace function public.bella_public_config_v3() returns table(live_web_enabled boolean,games_enabled boolean,radar_enabled boolean,maintenance_enabled boolean,announcement text,leaderboard_enabled boolean,content_ai_enabled boolean,wisdom_game_enabled boolean,proverb_game_enabled boolean,rumor_list_enabled boolean,box_game_enabled boolean,kuwait_quiz_enabled boolean,chat_ai_enabled boolean,voice_enabled boolean,ai_activities_enabled boolean,moments_enabled boolean,updated_at timestamptz) language sql stable security definer set search_path='' as $$ select c.live_web_enabled,c.games_enabled,c.radar_enabled,c.maintenance_enabled,c.announcement,c.leaderboard_enabled,c.content_ai_enabled,c.wisdom_game_enabled,c.proverb_game_enabled,c.rumor_list_enabled,c.box_game_enabled,c.kuwait_quiz_enabled,c.chat_ai_enabled,c.voice_enabled,c.ai_activities_enabled,c.moments_enabled,c.updated_at from public.bella_app_config c where c.id=1 $$;
revoke all on function public.bella_public_config_v3() from public; grant execute on function public.bella_public_config_v3() to anon,authenticated;

create or replace function public.bella_owner_config_v3() returns table(live_web_enabled boolean,games_enabled boolean,radar_enabled boolean,maintenance_enabled boolean,announcement text,ai_daily_limit integer,leaderboard_enabled boolean,content_ai_enabled boolean,wisdom_game_enabled boolean,proverb_game_enabled boolean,rumor_list_enabled boolean,box_game_enabled boolean,kuwait_quiz_enabled boolean,chat_ai_enabled boolean,voice_enabled boolean,ai_activities_enabled boolean,moments_enabled boolean,today_ai_used integer,today_chat_used integer,today_live_web_used integer,updated_at timestamptz) language plpgsql stable security definer set search_path='' as $$ begin if not public.is_bella_owner() then raise exception 'owner access required' using errcode='42501'; end if; return query select c.live_web_enabled,c.games_enabled,c.radar_enabled,c.maintenance_enabled,c.announcement,c.ai_daily_limit,c.leaderboard_enabled,c.content_ai_enabled,c.wisdom_game_enabled,c.proverb_game_enabled,c.rumor_list_enabled,c.box_game_enabled,c.kuwait_quiz_enabled,c.chat_ai_enabled,c.voice_enabled,c.ai_activities_enabled,c.moments_enabled,coalesce(u.requests,0),coalesce(u.chat_requests,0),coalesce(u.live_web_requests,0),c.updated_at from public.bella_app_config c left join public.bella_ai_daily_usage u on u.usage_day=current_date where c.id=1; end $$;
revoke all on function public.bella_owner_config_v3() from public,anon; grant execute on function public.bella_owner_config_v3() to authenticated;

create or replace function public.bella_owner_update_config_v3(p_live_web_enabled boolean,p_games_enabled boolean,p_radar_enabled boolean,p_maintenance_enabled boolean,p_announcement text,p_ai_daily_limit integer,p_leaderboard_enabled boolean,p_content_ai_enabled boolean,p_wisdom_game_enabled boolean,p_proverb_game_enabled boolean,p_rumor_list_enabled boolean,p_box_game_enabled boolean,p_kuwait_quiz_enabled boolean,p_chat_ai_enabled boolean,p_voice_enabled boolean,p_ai_activities_enabled boolean,p_moments_enabled boolean) returns table(live_web_enabled boolean,games_enabled boolean,radar_enabled boolean,maintenance_enabled boolean,announcement text,ai_daily_limit integer,leaderboard_enabled boolean,content_ai_enabled boolean,wisdom_game_enabled boolean,proverb_game_enabled boolean,rumor_list_enabled boolean,box_game_enabled boolean,kuwait_quiz_enabled boolean,chat_ai_enabled boolean,voice_enabled boolean,ai_activities_enabled boolean,moments_enabled boolean,today_ai_used integer,today_chat_used integer,today_live_web_used integer,updated_at timestamptz) language plpgsql security definer set search_path='' as $$ declare clean_announcement text:=left(trim(coalesce(p_announcement,'')),500); clean_limit integer:=greatest(0,least(coalesce(p_ai_daily_limit,0),100000)); begin if not public.is_bella_owner() then raise exception 'owner access required' using errcode='42501'; end if; update public.bella_app_config set live_web_enabled=coalesce(p_live_web_enabled,live_web_enabled),games_enabled=coalesce(p_games_enabled,games_enabled),radar_enabled=coalesce(p_radar_enabled,radar_enabled),maintenance_enabled=coalesce(p_maintenance_enabled,maintenance_enabled),announcement=clean_announcement,ai_daily_limit=clean_limit,leaderboard_enabled=coalesce(p_leaderboard_enabled,leaderboard_enabled),content_ai_enabled=coalesce(p_content_ai_enabled,content_ai_enabled),wisdom_game_enabled=coalesce(p_wisdom_game_enabled,wisdom_game_enabled),proverb_game_enabled=coalesce(p_proverb_game_enabled,proverb_game_enabled),rumor_list_enabled=coalesce(p_rumor_list_enabled,rumor_list_enabled),box_game_enabled=coalesce(p_box_game_enabled,box_game_enabled),kuwait_quiz_enabled=coalesce(p_kuwait_quiz_enabled,kuwait_quiz_enabled),chat_ai_enabled=coalesce(p_chat_ai_enabled,chat_ai_enabled),voice_enabled=coalesce(p_voice_enabled,voice_enabled),ai_activities_enabled=coalesce(p_ai_activities_enabled,ai_activities_enabled),moments_enabled=coalesce(p_moments_enabled,moments_enabled),updated_at=now(),updated_by=auth.uid() where id=1; return query select * from public.bella_owner_config_v3(); end $$;
revoke all on function public.bella_owner_update_config_v3(boolean,boolean,boolean,boolean,text,integer,boolean,boolean,boolean,boolean,boolean,boolean,boolean,boolean,boolean,boolean,boolean) from public,anon; grant execute on function public.bella_owner_update_config_v3(boolean,boolean,boolean,boolean,text,integer,boolean,boolean,boolean,boolean,boolean,boolean,boolean,boolean,boolean,boolean,boolean) to authenticated;

create or replace function public.bella_owner_player_detail(p_user_id uuid) returns table(user_id uuid,display_name text,xp integer,level integer,leaderboard_blocked boolean,has_game_score boolean) language plpgsql stable security definer set search_path='' as $$ begin if not public.is_bella_owner() then raise exception 'owner access required' using errcode='42501'; end if; return query select p.user_id,p.display_name,p.xp,p.level,coalesce(a.leaderboard_blocked,false),exists(select 1 from public.bella_game_scores g where g.user_id=p.user_id) from public.bella_profiles p left join public.bella_account_admin a on a.user_id=p.user_id where p.user_id=p_user_id; end $$;
create or replace function public.bella_owner_set_xp(p_user_id uuid,p_xp integer,p_reason text default null) returns table(xp integer,level integer) language plpgsql security definer set search_path='' as $$ declare actor uuid:=auth.uid(); old_xp integer; new_xp integer:=greatest(0,least(coalesce(p_xp,0),1000000)); new_level integer; why text:=nullif(left(trim(coalesce(p_reason,'')),240),''); begin if not public.is_bella_owner() then raise exception 'owner access required' using errcode='42501'; end if; if exists(select 1 from public.bella_owner_singleton o where o.slot=1 and o.user_id=p_user_id) then raise exception 'owner account cannot be modified here' using errcode='42501'; end if; select p.xp into old_xp from public.bella_profiles p where p.user_id=p_user_id for update; new_level:=greatest(1,floor(new_xp/100.0)::integer+1); update public.bella_profiles set xp=new_xp,level=new_level,updated_at=now() where user_id=p_user_id; insert into public.bella_admin_audit(actor_user_id,target_user_id,action,old_value,new_value,reason) values(actor,p_user_id,'set_xp',jsonb_build_object('xp',old_xp),jsonb_build_object('xp',new_xp,'level',new_level),why); return query select new_xp,new_level; end $$;
create or replace function public.bella_owner_reset_game_score(p_user_id uuid,p_reason text default null) returns boolean language plpgsql security definer set search_path='' as $$ declare actor uuid:=auth.uid(); why text:=nullif(left(trim(coalesce(p_reason,'')),240),''); old_value jsonb; begin if not public.is_bella_owner() then raise exception 'owner access required' using errcode='42501'; end if; select to_jsonb(g) into old_value from public.bella_game_scores g where g.user_id=p_user_id; delete from public.bella_game_scores where user_id=p_user_id; insert into public.bella_admin_audit(actor_user_id,target_user_id,action,old_value,new_value,reason) values(actor,p_user_id,'reset_game_score',coalesce(old_value,'{}'::jsonb),'{}'::jsonb,why); return true; end $$;
create or replace function public.bella_owner_set_leaderboard_block(p_user_id uuid,p_blocked boolean,p_reason text default null) returns boolean language plpgsql security definer set search_path='' as $$ declare actor uuid:=auth.uid(); old_blocked boolean:=false; new_blocked boolean:=coalesce(p_blocked,false); why text:=nullif(left(trim(coalesce(p_reason,'')),240),''); begin if not public.is_bella_owner() then raise exception 'owner access required' using errcode='42501'; end if; insert into public.bella_account_admin(user_id) values(p_user_id) on conflict(user_id) do nothing; select coalesce(a.leaderboard_blocked,false) into old_blocked from public.bella_account_admin a where a.user_id=p_user_id for update; update public.bella_account_admin set leaderboard_blocked=new_blocked,updated_at=now() where user_id=p_user_id; insert into public.bella_admin_audit(actor_user_id,target_user_id,action,old_value,new_value,reason) values(actor,p_user_id,'leaderboard_block',jsonb_build_object('blocked',old_blocked),jsonb_build_object('blocked',new_blocked),why); return new_blocked; end $$;
revoke all on function public.bella_owner_player_detail(uuid) from public,anon; revoke all on function public.bella_owner_set_xp(uuid,integer,text) from public,anon; revoke all on function public.bella_owner_reset_game_score(uuid,text) from public,anon; revoke all on function public.bella_owner_set_leaderboard_block(uuid,boolean,text) from public,anon; grant execute on function public.bella_owner_player_detail(uuid) to authenticated; grant execute on function public.bella_owner_set_xp(uuid,integer,text) to authenticated; grant execute on function public.bella_owner_reset_game_score(uuid,text) to authenticated; grant execute on function public.bella_owner_set_leaderboard_block(uuid,boolean,text) to authenticated;
